from tallybird.flags import Flags
from tallybird.onboarding import steps

MICROSOFT = {"calendar_provider": "microsoft", "plan": "pro"}
GOOGLE = {"calendar_provider": "google", "plan": "pro"}


def test_microsoft_users_can_skip_calendar_when_the_flag_is_on():
    flags = Flags.load(overrides={"calendar_skip_microsoft": True})
    assert steps(MICROSOFT, flags)[0].skippable
    assert not steps(GOOGLE, flags)[0].skippable


def test_nothing_changes_while_the_flag_is_off():
    assert not steps(MICROSOFT, Flags.load())[0].skippable
